{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "서울특별시 도시공원 조례상 공원 내 드론 비행 허용 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "도시공원 조례 제22조제1항에 따르면 누구든지 도시공원에서 법 제49조제1항 및 제2항 각 호의 행위를 하여서는 아니 된다. 따라서 공원 내 드론 비행이 법 제49조제1항·제2항 각 호의 금지행위에 해당하면 원칙적으로 허용되지 않는다. 다만 같은 조 제2항에 따라 공원관리청이 공익에 부합한다고 판단하여 허용한 행사의 경우 도시공원 관리에 현저한 지장을 초래하지 않는 범위에서 일부 상행위 등을 허용할 수 있으나, 이는 드론 비행 일반을 허용하는 근거가 아니다.",
          "b_ids": "도시공원:제22조제1항, 도시공원:제22조제2항"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
